import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadCinzel = makeLoadFont('Cinzel');

// Load fonts at module level
const { fontFamily: montserrat } = loadMontserrat();
const { fontFamily: cinzel } = loadCinzel();



export type CasinoOverlayProps = Record<string, any>;

const ChamferedBox: React.FC<{
  children: React.ReactNode;
  style?: React.CSSProperties;
  darkColor: string;
  lightColor: string;
}> = ({ children, style, darkColor, lightColor }) => {
  return (
    <div
      style={{
        // Gold Gradient Border
        background: "linear-gradient(135deg, #BF953F 0%, #FCF6BA 25%, #B38728 50%, #FBF5B7 75%, #AA771C 100%)",
        padding: "3px",
        clipPath: "polygon(15px 0, calc(100% - 15px) 0, 100% 15px, 100% calc(100% - 15px), calc(100% - 15px) 100%, 15px 100%, 0 calc(100% - 15px), 0 15px)",
        boxShadow: "0 10px 30px rgba(0,0,0,0.5)",
        ...style,
      }}
    >
      <div
        style={{
          // Inner Luxurious Gradient
          background: `linear-gradient(135deg, ${darkColor} 0%, ${lightColor} 100%)`,
          width: "100%",
          height: "100%",
          clipPath: "polygon(13px 0, calc(100% - 13px) 0, 100% 13px, 100% calc(100% - 13px), calc(100% - 13px) 100%, 13px 100%, 0 calc(100% - 13px), 0 13px)",
          padding: "15px 25px",
          display: "flex",
          flexDirection: "column",
          position: "relative",
        }}
      >
        {/* Subtle inner top highlight to enhance 3D luxurious feel */}
        <div style={{
            position: 'absolute',
            top: 0, left: 0, right: 0, height: '20px',
            background: 'linear-gradient(180deg, rgba(255,255,255,0.05) 0%, rgba(255,255,255,0) 100%)',
            pointerEvents: 'none'
        }} />
        {children}
      </div>
    </div>
  );
};

const CasinoOverlay: React.FC<CasinoOverlayProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 10,
  primaryColorDark = "#2e0404", // Very dark red
  primaryColorLight = "#8a0303", // Rich crimson red
  goldAccent = "#FBE285", // Bright gold for text
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Springs
  const balanceSpring = spring({ frame: frame - 15, fps, config: { damping: 14, stiffness: 100 } });
  const betSpring = spring({ frame: frame - 20, fps, config: { damping: 14, stiffness: 100 } });

  // Interpolations
  const balanceY = interpolate(balanceSpring, [0, 1], [50, 0]);
  const betY = interpolate(betSpring, [0, 1], [50, 0]);

  // Safe zones
  const bottomSafe = height * 0.05;
  const sideSafe = width * 0.05;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* LEFT SIDE STATS */}
      <div
        style={{
          position: "absolute",
          bottom: bottomSafe,
          left: sideSafe,
          display: "flex",
          flexDirection: "column",
          gap: "15px",
        }}
      >
        {/* Balance Box */}
        <ChamferedBox
          darkColor={primaryColorDark}
          lightColor={primaryColorLight}
          style={{
            transform: `translateY(${balanceY}px)`,
            opacity: balanceSpring,
            transition: "none",
          }}
        >
          <span style={{ 
            color: goldAccent, 
            fontFamily: cinzel, 
            fontWeight: 800, 
            fontSize: "24px", 
            letterSpacing: "2px",
            textShadow: "0px 2px 4px rgba(0,0,0,0.6)",
            alignSelf: "center"
          }}>
            BALANCE
          </span>
          <span style={{ 
            color: "white", 
            fontFamily: montserrat, 
            fontWeight: 800, 
            fontSize: "42px",
            lineHeight: "1.1",
            textShadow: "0px 2px 6px rgba(0,0,0,0.8)",
            alignSelf: "center"
          }}>
            &nbsp;
          </span>
        </ChamferedBox>
      </div>

      {/* RIGHT SIDE BET SIZE */}
      <div
        style={{
          position: "absolute",
          bottom: bottomSafe,
          right: sideSafe,
        }}
      >
        <ChamferedBox
          darkColor={primaryColorDark}
          lightColor={primaryColorLight}
          style={{
            transform: `translateY(${betY}px)`,
            opacity: betSpring,
            transition: "none",
          }}
        >
          <span style={{ 
            color: goldAccent, 
            fontFamily: cinzel, 
            fontWeight: 800, 
            fontSize: "22px", 
            letterSpacing: "2px",
            textShadow: "0px 2px 4px rgba(0,0,0,0.6)",
            alignSelf: "center"
          }}>
            BET SIZE
          </span>
          <span style={{ 
            color: "white", 
            fontFamily: montserrat, 
            fontWeight: 800, 
            fontSize: "36px",
            lineHeight: "1.2",
            textShadow: "0px 2px 6px rgba(0,0,0,0.8)",
            alignSelf: "center"
          }}>
            &nbsp;
          </span>
        </ChamferedBox>
      </div>

    </AbsoluteFill>
  );
};

export default CasinoOverlay;